/**
 * Engine Persistence & Damage Logbook -- EFB app UI.
 *
 * REWRITTEN FOR FSCOMPONENT, not React. The first version of this file
 * was written as a plain React functional component -- that was wrong
 * for this project: its tsconfig.json specifies
 * `"jsxFactory": "FSComponent.buildComponent"`, which means the JSX in
 * this file compiles against Microsoft's own FSComponent framework
 * (used throughout MSFS avionics/gauge development), not React.
 *
 * Key differences from the React version this replaces:
 *   - Components are classes extending DisplayComponent<Props>, not
 *     functions.
 *   - No hooks (no useState/useEffect). Instead: build the DOM once in
 *     render() using NodeReference (FSComponent.createRef) on anything
 *     that needs to change later, then update those refs' DOM nodes
 *     directly and imperatively (ref.instance.textContent = ...,
 *     ref.instance.style.width = ..., etc.) from a polling loop started
 *     in onAfterRender().
 *   - The activity log appends DOM nodes directly to a ref'd container
 *     rather than re-rendering a list.
 *   - Switching the active aircraft profile (via the dropdown) doesn't
 *     unmount/remount anything -- it re-initializes the in-memory
 *     logbook state and immediately pushes updated values into the
 *     same DOM references already on screen.
 *
 * HONEST CAVEAT: unlike aircraftProfiles.ts and wearModel.ts (which
 * were fully type-checked and runtime-tested against a real
 * TypeScript/Node environment), this file could NOT be verified the
 * same way -- the actual @microsoft/msfs-sdk package isn't something I
 * can install and check against here. This is a careful, best-effort
 * application of FSComponent's well-established conventions, not
 * confirmed-working code. Your build output is the real test.
 */

import {
  FSComponent, DisplayComponent, ComponentProps, VNode, NodeReference,
} from "@microsoft/msfs-sdk";
import {
  AircraftId, AircraftProfile, AIRCRAFT_PROFILES, AIRCRAFT_ORDER, detectProfileFromTitle,
} from "./aircraftProfiles";
import {
  LogbookState, SessionTrackers, createLogbook, createSessionTrackers, sample,
  applyStartConsequences, repairEngine, overhaulEngine, refillOil, repairFuelPump,
  repairFlaps, repairGear, repairBrakes, repairTires, repairLight, repairHydraulics,
  repairBattery, performHundredHourCheck, overhaulAirframe, Invoice,
} from "./wearModel";
import * as sv from "./simvars";

const POLL_MS = 2000;
const STORAGE_PREFIX = "engineLogbook";

function storageKey(aircraftId: string, tail: string): string {
  const safeTail = tail.replace(/[^A-Za-z0-9]/g, "") || "UNKNOWN";
  return `${STORAGE_PREFIX}:${aircraftId}:${safeTail}`;
}

function loadLogbook(profile: AircraftProfile, tail: string, title: string): LogbookState {
  try {
    const raw = localStorage.getItem(storageKey(profile.id, tail));
    if (raw) {
      const parsed = JSON.parse(raw) as LogbookState;
      const fresh = createLogbook(profile, tail, title);
      return { ...fresh, ...parsed, airframe: { ...fresh.airframe, ...parsed.airframe } };
    }
  } catch (e) {
    console.error("Failed to load logbook, starting fresh:", e);
  }
  return createLogbook(profile, tail, title);
}

function saveLogbook(state: LogbookState): void {
  try {
    localStorage.setItem(storageKey(state.aircraftId, state.tailNumber), JSON.stringify(state));
  } catch (e) {
    console.error("Failed to save logbook:", e);
  }
}

function costRange(profile: AircraftProfile, key: string): string {
  const entry = profile.repairCosts[key];
  if (typeof entry === "number") return `${profile.currencySymbol}${entry.toLocaleString()}`;
  return `${profile.currencySymbol}${entry.min.toLocaleString()}-${profile.currencySymbol}${entry.max.toLocaleString()}`;
}

function costAt(profile: AircraftProfile, key: string, wearFraction: number): string {
  const entry = profile.repairCosts[key];
  if (typeof entry === "number") return `${profile.currencySymbol}${entry.toLocaleString()}`;
  const cost = entry.min + (entry.max - entry.min) * Math.max(0, Math.min(1, wearFraction));
  return `${profile.currencySymbol}${Math.round(cost).toLocaleString()}`;
}

interface EngineCardProps extends ComponentProps {
  idx: number;
  profile: AircraftProfile;
  onRepair: () => void;
  onRefillOil: () => void;
  onRepairPump: () => void;
  onOverhaul: () => void;
}

class EngineCard extends DisplayComponent<EngineCardProps> {
  private wearLabel = FSComponent.createRef<HTMLDivElement>();
  private wearBar = FSComponent.createRef<HTMLDivElement>();
  private oilLabel = FSComponent.createRef<HTMLDivElement>();
  private oilBar = FSComponent.createRef<HTMLDivElement>();
  private pumpLabel = FSComponent.createRef<HTMLDivElement>();
  private muted = FSComponent.createRef<HTMLDivElement>();
  private repairBtn = FSComponent.createRef<HTMLButtonElement>();
  private pumpBtn = FSComponent.createRef<HTMLButtonElement>();

  public update(rec: LogbookState["engines"][number]): void {
    const p = this.props.profile;
    this.wearLabel.instance.textContent = `Wear: ${rec.wearPercent.toFixed(1)}%`;
    this.wearBar.instance.style.width = `${rec.wearPercent}%`;
    this.oilLabel.instance.textContent = `Oil: ${rec.oilQuantityPercent.toFixed(0)}%`;
    this.oilBar.instance.style.width = `${rec.oilQuantityPercent}%`;
    this.pumpLabel.instance.textContent = `Fuel pump wear: ${rec.fuelPumpWearPercent.toFixed(1)}%`;
    const tboOverdue = rec.totalHours >= p.engineTboHours;
    this.muted.instance.textContent =
      `Hours toward TBO: ${rec.totalHours.toFixed(0)} / ${p.engineTboHours.toFixed(0)}` +
      (tboOverdue ? " \u26a0 OVERDUE" : "") +
      ` | Exceedances: ${rec.exceedanceCount} | Failures: ${rec.failureCount}`;
    this.repairBtn.instance.textContent = `Repair Engine (${costAt(p, "engine_repair", rec.wearPercent / 100)})`;
    this.pumpBtn.instance.textContent = `Service Fuel Pump (${costAt(p, "fuel_pump_service", rec.fuelPumpWearPercent / 100)})`;
  }

  render(): VNode {
    const p = this.props.profile;
    return (
      <div class="engine-card">
        <div class="engine-card__title">Engine {this.props.idx}</div>
        <div class="engine-card__row" ref={this.wearLabel}>Wear: --%</div>
        <div class="engine-card__bar"><div class="engine-card__bar-fill" ref={this.wearBar} /></div>
        <div class="engine-card__row" ref={this.oilLabel}>Oil: --%</div>
        <div class="engine-card__bar"><div class="engine-card__bar-fill" ref={this.oilBar} /></div>
        <div class="engine-card__row" ref={this.pumpLabel}>Fuel pump wear: --%</div>
        <div class="engine-card__muted" ref={this.muted}>--</div>
        <div class="engine-card__buttons">
          <button ref={this.repairBtn} onClick={() => this.props.onRepair()}>Repair Engine ({costRange(p, "engine_repair")})</button>
          <button onClick={() => this.props.onRefillOil()}>Refill Oil</button>
          <button ref={this.pumpBtn} onClick={() => this.props.onRepairPump()}>Service Fuel Pump ({costRange(p, "fuel_pump_service")})</button>
          <button onClick={() => this.props.onOverhaul()}>Overhaul Engine ({costRange(p, "engine_overhaul")})</button>
        </div>
      </div>
    );
  }
}

interface AirframeCardProps extends ComponentProps {
  profile: AircraftProfile;
  onRepairFlaps: () => void;
  onRepairGear: () => void;
  onRepairBrakes: () => void;
}

class AirframeCard extends DisplayComponent<AirframeCardProps> {
  private flapLabel = FSComponent.createRef<HTMLDivElement>();
  private gearLabel = FSComponent.createRef<HTMLDivElement>();
  private brakeLabel = FSComponent.createRef<HTMLDivElement>();
  private muted = FSComponent.createRef<HTMLDivElement>();
  private flapBtn = FSComponent.createRef<HTMLButtonElement>();
  private gearBtn = FSComponent.createRef<HTMLButtonElement>();
  private brakeBtn = FSComponent.createRef<HTMLButtonElement>();

  public update(af: LogbookState["airframe"]): void {
    const p = this.props.profile;
    this.flapLabel.instance.textContent = `Flap wear: ${af.flapWearPercent.toFixed(1)}%${af.flapJammed ? " \u26a0 JAMMED" : ""}`;
    this.gearLabel.instance.textContent = `Gear wear: ${af.gearWearPercent.toFixed(1)}%${af.gearJammed ? " \u26a0 JAMMED" : ""}`;
    this.brakeLabel.instance.textContent = `Brake wear: ${af.brakeWearPercent.toFixed(1)}%${af.brakeFaded ? " \u26a0 FADED" : ""}`;
    this.muted.instance.textContent =
      `Vfe ${p.vfeKias} / Vle ${p.vleKias} kt | Hard landings: ${af.hardLandingCount} | Hard braking: ${af.brakeHardUseCount}`;
    this.flapBtn.instance.textContent = `Repair Flaps (${costAt(p, "flap_repair", af.flapWearPercent / 100)})`;
    this.gearBtn.instance.textContent = `Repair Gear (${costAt(p, "gear_repair", af.gearWearPercent / 100)})`;
    this.brakeBtn.instance.textContent = `Repair Brakes (${costAt(p, "brake_repair", af.brakeWearPercent / 100)})`;
  }

  render(): VNode {
    return (
      <div class="airframe-card">
        <div class="airframe-card__title">Flaps, Gear &amp; Brakes</div>
        <div ref={this.flapLabel}>Flap wear: --%</div>
        <div ref={this.gearLabel}>Gear wear: --%</div>
        <div ref={this.brakeLabel}>Brake wear: --%</div>
        <div class="airframe-card__muted" ref={this.muted}>--</div>
        <div class="airframe-card__buttons">
          <button ref={this.flapBtn} onClick={() => this.props.onRepairFlaps()}>Repair Flaps</button>
          <button ref={this.gearBtn} onClick={() => this.props.onRepairGear()}>Repair Gear</button>
          <button ref={this.brakeBtn} onClick={() => this.props.onRepairBrakes()}>Repair Brakes</button>
        </div>
      </div>
    );
  }
}

interface SystemsCardProps extends ComponentProps {
  profile: AircraftProfile;
  onRepairTires: () => void;
  onRepairLight: (c: "landing_taxi" | "nav_beacon") => void;
  onRepairHydraulics: () => void;
  onRepairBattery: () => void;
  onHundredHourCheck: () => void;
  onOverhaulAirframe: () => void;
}

class SystemsCard extends DisplayComponent<SystemsCardProps> {
  private tireLabel = FSComponent.createRef<HTMLDivElement>();
  private hydraulicLabel = FSComponent.createRef<HTMLDivElement>();
  private batteryLabel = FSComponent.createRef<HTMLDivElement>();
  private lightsLine = FSComponent.createRef<HTMLDivElement>();
  private airframeLine = FSComponent.createRef<HTMLDivElement>();
  private hundredHourLine = FSComponent.createRef<HTMLDivElement>();
  private tireBtn = FSComponent.createRef<HTMLButtonElement>();
  private landingTaxiBtn = FSComponent.createRef<HTMLButtonElement>();
  private navBeaconBtn = FSComponent.createRef<HTMLButtonElement>();
  private hydraulicBtn = FSComponent.createRef<HTMLButtonElement>();
  private batteryBtn = FSComponent.createRef<HTMLButtonElement>();

  public update(af: LogbookState["airframe"]): void {
    const p = this.props.profile;
    this.tireLabel.instance.textContent = `Tire wear: ${af.tireWearPercent.toFixed(1)}%${af.tireBlown ? " \u26a0 BLOWN" : ""}`;
    this.hydraulicLabel.instance.textContent = `Hydraulic wear: ${af.hydraulicWearPercent.toFixed(1)}%${af.hydraulicFailed ? " \u26a0 FAILED" : ""}`;
    this.batteryLabel.instance.textContent = `Battery wear: ${af.batteryWearPercent.toFixed(1)}%${af.batteryWeak ? " \u26a0 WEAK" : ""}`;
    this.lightsLine.instance.textContent =
      `Landing/Taxi: ${af.lightHours.landing_taxi.toFixed(0)}h${af.lightBurnedOut.landing_taxi ? " \u26a0" : ""}` +
      ` | Nav/Beacon: ${af.lightHours.nav_beacon.toFixed(0)}h${af.lightBurnedOut.nav_beacon ? " \u26a0" : ""}`;
    this.airframeLine.instance.textContent = `Airframe hours: ${af.airframeHours.toFixed(0)} / ${p.airframeOverhaulHours.toFixed(0)}`;

    const hrs = af.hoursSince100hrCheck;
    const interval = p.hundredHourCheckIntervalHours;
    const grace = p.hundredHourCheckGraceHours;
    const status = hrs >= interval + grace ? " \u26a0 OVERDUE" : hrs >= interval ? ` \u26a0 DUE (${grace.toFixed(0)}h grace)` : "";
    this.hundredHourLine.instance.textContent =
      `100-hour check: ${hrs.toFixed(1)} / ${interval.toFixed(0)} hrs${status} (completed ${af.hundredHourCheckCount}x)`;

    this.tireBtn.instance.textContent = `Replace Tires (${costAt(p, "tire_replacement", af.tireWearPercent / 100)})`;
    this.landingTaxiBtn.instance.textContent = `Replace Landing/Taxi Bulb (${costAt(p, "light_repair_landing_taxi", af.lightHours.landing_taxi / p.lightLifeHours.landing_taxi)})`;
    this.navBeaconBtn.instance.textContent = `Replace Nav/Beacon Bulb (${costAt(p, "light_repair_nav_beacon", af.lightHours.nav_beacon / p.lightLifeHours.nav_beacon)})`;
    this.hydraulicBtn.instance.textContent = `Service Hydraulics (${costAt(p, "hydraulic_service", af.hydraulicWearPercent / 100)})`;
    this.batteryBtn.instance.textContent = `Replace Battery (${costAt(p, "battery_replacement", af.batteryWearPercent / 100)})`;
  }

  render(): VNode {
    const p = this.props.profile;
    return (
      <div class="systems-card">
        <div class="systems-card__title">Tires, Lights, Hydraulics &amp; Battery</div>
        <div ref={this.tireLabel}>Tire wear: --%</div>
        <div ref={this.hydraulicLabel}>Hydraulic wear: --%</div>
        <div ref={this.batteryLabel}>Battery wear: --%</div>
        <div class="systems-card__muted" ref={this.lightsLine}>--</div>
        <div class="systems-card__muted" ref={this.airframeLine}>--</div>
        <div class="systems-card__muted" ref={this.hundredHourLine}>--</div>
        <div class="systems-card__buttons">
          <button ref={this.tireBtn} onClick={() => this.props.onRepairTires()}>Replace Tires</button>
          <button ref={this.landingTaxiBtn} onClick={() => this.props.onRepairLight("landing_taxi")}>Replace Landing/Taxi Bulb</button>
          <button ref={this.navBeaconBtn} onClick={() => this.props.onRepairLight("nav_beacon")}>Replace Nav/Beacon Bulb</button>
          <button ref={this.hydraulicBtn} onClick={() => this.props.onRepairHydraulics()}>Service Hydraulics</button>
          <button ref={this.batteryBtn} onClick={() => this.props.onRepairBattery()}>Replace Battery</button>
          <button onClick={() => this.props.onHundredHourCheck()}>100-Hour Check ({costRange(p, "hundred_hour_check")})</button>
          <button onClick={() => this.props.onOverhaulAirframe()}>Overhaul Airframe ({costRange(p, "airframe_overhaul")})</button>
        </div>
      </div>
    );
  }
}

export class EngineLogbookApp extends DisplayComponent<ComponentProps> {
  private root = FSComponent.createRef<HTMLDivElement>();
  private titleEl = FSComponent.createRef<HTMLHeadingElement>();
  private badgeEl = FSComponent.createRef<HTMLSpanElement>();
  private dropdown = FSComponent.createRef<HTMLSelectElement>();
  private subEl = FSComponent.createRef<HTMLDivElement>();
  private enginesContainer = FSComponent.createRef<HTMLDivElement>();
  private airframeCardRef = FSComponent.createRef<AirframeCard>();
  private systemsCardRef = FSComponent.createRef<SystemsCard>();
  private logBody = FSComponent.createRef<HTMLDivElement>();

  private engineCards: EngineCard[] = [];
  private profile: AircraftProfile | null = null;
  private state: LogbookState | null = null;
  private trackers: SessionTrackers | null = null;
  private pollHandle: number | null = null;

  onAfterRender(_node: VNode): void {
    this.populateDropdown();
    const title = sv.aircraftTitle();
    const detected = detectProfileFromTitle(title);
    if (detected) {
      this.selectProfile(detected, "auto");
    } else {
      this.badgeEl.instance.textContent = `Couldn't auto-detect ("${title}") -- pick one:`;
      this.badgeEl.instance.className = "engine-logbook__badge engine-logbook__badge--manual";
    }

    this.dropdown.instance.addEventListener("change", () => {
      const id = this.dropdown.instance.value as AircraftId;
      if (id && AIRCRAFT_PROFILES[id]) {
        this.selectProfile(AIRCRAFT_PROFILES[id], "manual");
      }
    });
  }

  private populateDropdown(): void {
    const select = this.dropdown.instance;
    select.innerHTML = "";
    const placeholder = document.createElement("option");
    placeholder.value = "";
    placeholder.textContent = "Select aircraft...";
    placeholder.disabled = true;
    select.appendChild(placeholder);
    for (const id of AIRCRAFT_ORDER) {
      const opt = document.createElement("option");
      opt.value = id;
      opt.textContent = AIRCRAFT_PROFILES[id].displayName;
      select.appendChild(opt);
    }
  }

  private selectProfile(profile: AircraftProfile, mode: "auto" | "manual"): void {
    this.profile = profile;
    this.dropdown.instance.value = profile.id;
    this.badgeEl.instance.textContent = mode === "auto" ? "\u2713 auto-detected" : "manually selected";
    this.badgeEl.instance.className = `engine-logbook__badge engine-logbook__badge--${mode}`;
    this.titleEl.instance.textContent = `${profile.displayName} Engine Logbook`;

    const tail = sv.tailNumber();
    this.state = loadLogbook(profile, tail, profile.displayName);
    this.trackers = createSessionTrackers(profile);
    this.appendLog(`Detected ${profile.displayName}, tail ${tail}.`);

    const consequences = applyStartConsequences(profile, this.state);
    consequences.logs.forEach((l) => this.appendLog(l));
    for (const idxStr of Object.keys(consequences.engineFailures)) {
      const idx = Number(idxStr);
      if (consequences.engineFailures[idx]) {
        sv.setFailed(idx, true).catch((e) => this.appendLog(`[info] engine ${idx} failure not settable: ${e}`));
      }
    }
    for (const idxStr of Object.keys(consequences.fuelPumpFailures)) {
      const idx = Number(idxStr);
      if (consequences.fuelPumpFailures[idx]) {
        sv.setFuelPumpOn(idx, false).catch((e) => this.appendLog(`[info] engine ${idx} fuel pump not settable: ${e}`));
      }
    }
    saveLogbook(this.state);

    this.subEl.instance.textContent =
      `${this.state.title} | Tail ${this.state.tailNumber} | Maintenance spend: ${profile.currencySymbol}${this.state.totalSpent.toFixed(2)}`;

    this.rebuildEngineCards();
    this.refreshAll();

    if (this.pollHandle !== null) {
      window.clearInterval(this.pollHandle);
    }
    this.pollHandle = window.setInterval(() => this.poll(), POLL_MS);
  }

  private rebuildEngineCards(): void {
    if (!this.profile) return;
    this.enginesContainer.instance.innerHTML = "";
    this.engineCards = [];
    for (const idx of this.profile.engineIndices) {
      const cardRef = FSComponent.createRef<EngineCard>();
      FSComponent.render(
        <EngineCard
          ref={cardRef}
          idx={idx}
          profile={this.profile}
          onRepair={() => this.doRepair((p, s) => repairEngine(p, s, idx))}
          onRefillOil={() => this.doRepair((p, s) => refillOil(p, s, idx))}
          onRepairPump={() => this.doRepair((p, s) => repairFuelPump(p, s, idx))}
          onOverhaul={() => this.doRepair((p, s) => overhaulEngine(p, s, idx))}
        />,
        this.enginesContainer.instance,
      );
      if (cardRef.instance) this.engineCards.push(cardRef.instance);
    }
  }

  private doRepair(fn: (p: AircraftProfile, s: LogbookState) => Invoice | null): void {
    if (!this.profile || !this.state) return;
    const invoice = fn(this.profile, this.state);
    if (invoice) {
      this.appendLog(
        `Invoice #${invoice.number}: ${invoice.lineItems.map((li) => li.description).join(", ")} -- ${this.profile.currencySymbol}${invoice.total.toFixed(2)}`,
      );
      this.appendLog(`Total maintenance spend to date: ${this.profile.currencySymbol}${this.state.totalSpent.toFixed(2)}`);
    }
    saveLogbook(this.state);
    this.refreshAll();
  }

  private refreshAll(): void {
    if (!this.profile || !this.state) return;
    this.subEl.instance.textContent =
      `${this.state.title} | Tail ${this.state.tailNumber} | Maintenance spend: ${this.profile.currencySymbol}${this.state.totalSpent.toFixed(2)}`;
    this.profile.engineIndices.forEach((idx, i) => {
      const rec = this.state!.engines[idx];
      const card = this.engineCards[i];
      if (rec && card) card.update(rec);
    });
    if (this.airframeCardRef.instance) this.airframeCardRef.instance.update(this.state.airframe);
    if (this.systemsCardRef.instance) this.systemsCardRef.instance.update(this.state.airframe);
  }

  private appendLog(msg: string): void {
    const line = document.createElement("div");
    line.className = "activity-log__line";
    line.textContent = msg;
    this.logBody.instance.appendChild(line);
    while (this.logBody.instance.children.length > 500) {
      this.logBody.instance.removeChild(this.logBody.instance.firstChild as ChildNode);
    }
    this.logBody.instance.scrollTop = this.logBody.instance.scrollHeight;
  }

  private poll(): void {
    if (!this.profile || !this.state || !this.trackers) return;
    const profile = this.profile;
    const hasCenterGear = profile.id === "duke";
    const gearPercent = hasCenterGear ? sv.gearPercentCenter() : sv.gearPercentLeft();

    const engines: Record<number, any> = {};
    const generatorOn: boolean[] = [];
    for (const idx of profile.engineIndices) {
      engines[idx] = {
        combustionOn: sv.combustionOn(idx),
        oilTempC: sv.oilTempC(idx),
        chtC: sv.chtC(idx),
        oilPressPsi: sv.oilPressPsi(idx),
        manifoldPressInHg: sv.manifoldPressInHg(idx),
        rpm: sv.rpm(idx),
        fuelPressPsi: sv.fuelPressPsi(idx),
        elapsedTimeHr: sv.elapsedTimeHr(idx),
      };
      generatorOn.push(sv.generatorOn(idx));
    }

    sample(
      profile, this.state, this.trackers,
      {
        dtSec: POLL_MS / 1000,
        engines,
        airframe: {
          airspeedKias: sv.airspeedKias(),
          groundSpeedKt: sv.groundSpeedKt(),
          flapsPercent: sv.flapsPercent(),
          gearPercent,
          onGround: sv.onGround(),
          verticalSpeedFpm: sv.verticalSpeedFpm(),
          totalWeightLb: sv.totalWeightLb(),
          brakeLeftPercent: sv.brakeLeftPercent(),
          brakeRightPercent: sv.brakeRightPercent(),
          landingLightOn: sv.landingLightOn(),
          taxiLightOn: sv.taxiLightOn(),
          navLightOn: sv.navLightOn(),
          beaconLightOn: sv.beaconLightOn(),
          generatorOn,
        },
      },
      (msg) => this.appendLog(msg),
    );

    if (this.state.airframe.flapJammed) {
      sv.holdFlapPosition(sv.flapsPercent()).catch(() => {});
    }
    if (this.state.airframe.gearJammed) {
      sv.holdGearPosition(gearPercent, hasCenterGear).forEach((p) => p.catch(() => {}));
    }
    if (this.state.airframe.brakeFaded) {
      const cap = profile.brakeFadeEffectivenessCapPercent;
      const l = sv.capBrakePosition(cap, sv.brakeLeftPercent());
      if (l) l.catch(() => {});
    }

    saveLogbook(this.state);
    this.refreshAll();
  }

  destroy(): void {
    if (this.pollHandle !== null) window.clearInterval(this.pollHandle);
    super.destroy();
  }

  render(): VNode {
    return (
      <div class="engine-logbook" ref={this.root}>
        <header class="engine-logbook__header">
          <div class="engine-logbook__title-row">
            <h2 ref={this.titleEl}>Engine Logbook</h2>
            <div class="engine-logbook__selector">
              <span class="engine-logbook__badge" ref={this.badgeEl}>detecting...</span>
              <select class="engine-logbook__dropdown" ref={this.dropdown} />
            </div>
          </div>
          <div class="engine-logbook__sub" ref={this.subEl}>--</div>
        </header>

        <div class="engine-logbook__engines" ref={this.enginesContainer} />

        <AirframeCard
          ref={this.airframeCardRef}
          profile={this.profile ?? AIRCRAFT_PROFILES.dc3}
          onRepairFlaps={() => this.doRepair(repairFlaps)}
          onRepairGear={() => this.doRepair(repairGear)}
          onRepairBrakes={() => this.doRepair(repairBrakes)}
        />

        <SystemsCard
          ref={this.systemsCardRef}
          profile={this.profile ?? AIRCRAFT_PROFILES.dc3}
          onRepairTires={() => this.doRepair(repairTires)}
          onRepairLight={(c) => this.doRepair((p, s) => repairLight(p, s, c))}
          onRepairHydraulics={() => this.doRepair(repairHydraulics)}
          onRepairBattery={() => this.doRepair(repairBattery)}
          onHundredHourCheck={() => this.doRepair(performHundredHourCheck)}
          onOverhaulAirframe={() => this.doRepair(overhaulAirframe)}
        />

        <div class="activity-log">
          <div class="activity-log__title">Activity Log</div>
          <div class="activity-log__body" ref={this.logBody} />
        </div>
      </div>
    );
  }
}

export default EngineLogbookApp;
