/**
 * SimVar access for the Engine Persistence & Damage Logbook EFB app.
 *
 * Unlike the desktop Python version -- which had to work around real
 * bugs in the `SimConnect` PyPI package's own unit table (an invalid
 * "inHG." unit string on manifold pressure, oil temp/CHT silently in
 * Rankine instead of Celsius) -- this in-sim version requests units
 * directly by name through the standard global SimVar API used
 * throughout MSFS's JS gauge/instrument framework ("celsius", "psi",
 * "inHg", etc.), so those specific unit bugs don't apply here. The EFB
 * API itself (Container/App/AppView) is purely about app/view
 * management, not sim data access -- SimVar reads/writes go through
 * this same global API regardless of whether the calling code is an
 * EFB app or a panel gauge.
 *
 * HONEST CAVEAT (unchanged from the earlier desktop-only version of
 * this file): I can type-check and unit-test the pure logic in this
 * project (aircraftProfiles.ts, wearModel.ts) because I have a real
 * TypeScript/Node environment available. I do NOT have access to a
 * running MSFS instance, so the actual SimVar names/units requested
 * here cannot be verified against the live sim the way the logic
 * above was verified. If a reading looks wrong once you actually test
 * this in-sim, this file -- not wearModel.ts -- is almost certainly
 * where the fix belongs.
 */

declare const SimVar: {
  GetSimVarValue(name: string, unit: "string"): string;
  GetSimVarValue(name: string, unit: string): number;
  SetSimVarValue: (name: string, unit: string, value: number) => Promise<void>;
};

export function combustionOn(idx: number): boolean {
  return SimVar.GetSimVarValue(`GENERAL ENG COMBUSTION:${idx}`, "bool") !== 0;
}

export function oilTempC(idx: number): number {
  return SimVar.GetSimVarValue(`GENERAL ENG OIL TEMPERATURE:${idx}`, "celsius");
}

export function chtC(idx: number): number {
  return SimVar.GetSimVarValue(`RECIP ENG CYLINDER HEAD TEMPERATURE:${idx}`, "celsius");
}

export function oilPressPsi(idx: number): number {
  return SimVar.GetSimVarValue(`GENERAL ENG OIL PRESSURE:${idx}`, "psi");
}

export function manifoldPressInHg(idx: number): number {
  return SimVar.GetSimVarValue(`RECIP ENG MANIFOLD PRESSURE:${idx}`, "inHg");
}

export function rpm(idx: number): number {
  return SimVar.GetSimVarValue(`GENERAL ENG RPM:${idx}`, "rpm");
}

export function fuelPressPsi(idx: number): number {
  return SimVar.GetSimVarValue(`GENERAL ENG FUEL PRESSURE:${idx}`, "psi");
}

export function elapsedTimeHr(idx: number): number {
  return SimVar.GetSimVarValue(`GENERAL ENG ELAPSED TIME:${idx}`, "hours");
}

export function generatorOn(idx: number): boolean {
  return SimVar.GetSimVarValue(`GENERAL ENG GENERATOR SWITCH:${idx}`, "bool") !== 0;
}

export function aircraftTitle(): string {
  return SimVar.GetSimVarValue("ATC MODEL", "string") || SimVar.GetSimVarValue("TITLE", "string") || "";
}

export function tailNumber(): string {
  return SimVar.GetSimVarValue("ATC ID", "string") || "UNKNOWN";
}

export function airspeedKias(): number {
  return SimVar.GetSimVarValue("AIRSPEED INDICATED", "knots");
}

export function groundSpeedKt(): number {
  return SimVar.GetSimVarValue("GROUND VELOCITY", "knots");
}

export function flapsPercent(): number {
  return SimVar.GetSimVarValue("TRAILING EDGE FLAPS LEFT PERCENT", "percent");
}

/** Center (nose) gear -- correct for tricycle-gear aircraft (Duke). */
export function gearPercentCenter(): number {
  return SimVar.GetSimVarValue("GEAR CENTER POSITION", "percent");
}

/** Left main gear -- correct for taildraggers with no nose gear (DC-3/C-46/Beech 18). */
export function gearPercentLeft(): number {
  return SimVar.GetSimVarValue("GEAR LEFT POSITION", "percent");
}

export function onGround(): boolean {
  return SimVar.GetSimVarValue("SIM ON GROUND", "bool") !== 0;
}

export function verticalSpeedFpm(): number {
  return SimVar.GetSimVarValue("VERTICAL SPEED", "feet per minute");
}

export function totalWeightLb(): number {
  return SimVar.GetSimVarValue("TOTAL WEIGHT", "pounds");
}

/** Raw axis position, conventionally +/-16384 -- normalized to 0-100%. */
export function brakeLeftPercent(): number {
  const raw = SimVar.GetSimVarValue("BRAKE LEFT POSITION", "position");
  return Math.max(0, Math.min(100, (raw / 16384) * 100));
}

export function brakeRightPercent(): number {
  const raw = SimVar.GetSimVarValue("BRAKE RIGHT POSITION", "position");
  return Math.max(0, Math.min(100, (raw / 16384) * 100));
}

export function landingLightOn(): boolean {
  return SimVar.GetSimVarValue("LIGHT LANDING", "bool") !== 0;
}
export function taxiLightOn(): boolean {
  return SimVar.GetSimVarValue("LIGHT TAXI", "bool") !== 0;
}
export function navLightOn(): boolean {
  return SimVar.GetSimVarValue("LIGHT NAV", "bool") !== 0;
}
export function beaconLightOn(): boolean {
  return SimVar.GetSimVarValue("LIGHT BEACON", "bool") !== 0;
}

// --- Writes (best-effort -- see README Limitations: not every write
// physically sticks on every aircraft, so these are wrapped in
// try/catch by the caller and treated as warning-only if they fail) ---

export function setFailed(idx: number, failed: boolean): Promise<void> {
  return SimVar.SetSimVarValue(`GENERAL ENG FAILED:${idx}`, "bool", failed ? 1 : 0);
}

export function setFuelPumpOn(idx: number, on: boolean): Promise<void> {
  return SimVar.SetSimVarValue(`GENERAL ENG FUEL PUMP ON:${idx}`, "bool", on ? 1 : 0);
}

export function holdGearPosition(percent: number, hasCenterGear: boolean): Promise<void>[] {
  const writes = [
    SimVar.SetSimVarValue("GEAR LEFT POSITION", "percent", percent),
    SimVar.SetSimVarValue("GEAR RIGHT POSITION", "percent", percent),
  ];
  if (hasCenterGear) writes.push(SimVar.SetSimVarValue("GEAR CENTER POSITION", "percent", percent));
  return writes;
}

export function holdFlapPosition(percent: number): Promise<void> {
  return SimVar.SetSimVarValue("TRAILING EDGE FLAPS LEFT PERCENT", "percent", percent);
}

export function capBrakePosition(capPercent: number, current: number): Promise<void> | null {
  if (current <= capPercent) return null;
  const rawCap = (capPercent / 100) * 16384;
  return SimVar.SetSimVarValue("BRAKE LEFT POSITION", "position", rawCap);
}
