  takeoffPowerTimeLimitMin: number;
  oilPressureStartupGraceSec: number;
  oilPressureMinRpmToCheck: number;

  wearPerRunningHour: number;
  wearPerExceedanceSample: number;
  wearPerHardExceedance: number;
  wearWarnThreshold: number;
  wearRoughRunningThreshold: number;
  wearFailureRiskThreshold: number;
  failureChanceAtMaxWear: number;

  oilCapacityQuarts: number;
  oilConsumptionQtPerHour: number;
  oilLeakQtPerHourWhenDamaged: number;
  oilLeakStartsAtWearPercent: number;
  oilLowWarningPercent: number;
  oilCriticalPercent: number;
  oilCriticalWearMultiplier: number;

  fuelPressLowPsi: number;
