  flapWearPerSevereOverspeed: number;
  flapWearPerCycle: number;
  flapWarnThreshold: number;
  flapJamRiskThreshold: number;
  flapJamChanceAtMaxWear: number;

  vleKias: number;
  gearWearPerOverspeedSample: number;
  gearWearPerCycle: number;
  landingVsFirmFpm: number;
