  brakeHardBrakingApplicationPct: number;
  brakeWearPerUseSample: number;
  brakeWearPerHardBrakeSample: number;
  brakeWarnThreshold: number;
  brakeFadeRiskThreshold: number;
  brakeFadeChanceAtMaxWear: number;
  brakeFadeEffectivenessCapPercent: number;

  tireWearPerCycle: number;
  tireWearPerHardLandingBonus: number;
  tireWarnThreshold: number;
  tireBlowoutRiskThreshold: number;
  tireBlowoutChanceAtMaxWear: number;

  lightLifeHours: { landing_taxi: number; nav_beacon: number };
  lightWarnLifeFraction: number;
  lightBurnoutChancePerHourPastLife: number;

  hydraulicWearPerGearCycle: number;
  hydraulicWearPerFlapCycle: number;
