export const AIRCRAFT_PROFILES: Record<AircraftId, AircraftProfile> = {
  dc3: DC3, c46: C46, beech18: BEECH18, duke: DUKE,
};

export const AIRCRAFT_ORDER: AircraftId[] = ["dc3", "c46", "beech18", "duke"];

/**
 * Matches a loaded aircraft's title string against every profile's
 * titleMatches list (case-insensitive substring match, same logic as
 * each desktop app's matches_xxx() function). Returns the first match,
 * or null if nothing matches -- callers should fall back to showing
 * the manual dropdown selector when this returns null.
 */
export function detectProfileFromTitle(title: string): AircraftProfile | null {
  const lower = title.toLowerCase();
  for (const id of AIRCRAFT_ORDER) {
    const profile = AIRCRAFT_PROFILES[id];
    if (profile.titleMatches.some((m) => lower.includes(m))) {
      return profile;
    }
  }
  return null;
}

export function computeRepairCost(profile: AircraftProfile, key: string, wearFraction?: number): number {
  const entry = profile.repairCosts[key];
  if (entry === undefined) return 0;
  if (typeof entry === "number") return entry;
  const frac = wearFraction === undefined ? 0 : Math.max(0, Math.min(1, wearFraction));
  return entry.min + (entry.max - entry.min) * frac;
}
